   "en": "Carrera De La Primavera Turns Madrid Red For Europe’s First Chinese New Year Running Race",
   "pt": "Carrera De La Primavera Pinta Madrid De Vermelho Na Primeira Corrida Do Ano Novo Chinês Na Europa",
   "es": "La Carrera De La Primavera Tiñe Madrid De Rojo En La Primera Carrera De Año Nuevo Chino De Europa",
   "fr": "La Carrera De La Primavera Peint Madrid En Rouge Pour La Première Course Du Nouvel An Chinois En Europe",
