  "card-s16__field__deck": {
   "en": "More than 6,000 runners took new routes linking Madrid Río with the Casa de Campo as the Carrera de la Primavera closed the Año del Caballo weekend.",
   "pt": "Mais de 6.000 corredores percorreram novos percursos entre o Madrid Río e a Casa de Campo, numa Carrera de la Primavera que encerrou o fim de semana do Ano do Cavalo.",
   "es": "Más de 6.000 corredores recorrieron nuevos trazados entre Madrid Río y la Casa de Campo, en una Carrera de la Primavera que cerró el fin de semana del Año del Caballo.",
   "fr": "Plus de 6 000 coureurs ont emprunté de nouveaux parcours reliant Madrid Río à la Casa de Campo, la Carrera de la Primavera clôturant le week-end de l’Año del Caballo.",
   "it": "Oltre 6.000 corridori hanno percorso nuovi tracciati tra Madrid Río e la Casa de Campo, con la Carrera de la Primavera che ha chiuso il weekend dell’Año del Caballo."
  },
